mapper.select:
/* Attd16Mapper.selectLeaveUsageCalendarList */ WITH RECURSIVE date_seq AS ( SELECT STR_TO_DATE(#{monthStart}, '%Y%m%d') AS D
UNION ALL
SELECT D + INTERVAL 1 DAY FROM date_seq WHERE D < STR_TO_DATE(#{monthEnd}, '%Y%m%d') )
, node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
/* SELECT 컬럼 순서 = LeaveUsageCalendarRowResult 생성자 인자 순서와 1:1 (record 매핑). PII 최소화: LEAVE_REASON / EVIDENCE_FILE_ID / 연락처 / 이메일 / 생년월일은 내려주지 않는다. */ SELECT DATE_FORMAT(D.D, '%Y%m%d') AS dateYmd , LU.USER_CD AS userCd , U.USER_NM AS userNm , U.NODE_CD AS nodeCd , N.NODE_NM AS nodeNm , LU.LEAVE_CD AS leaveCd , LT.LEAVE_NM AS leaveNm , LU.USE_UNIT_TYPE AS useUnitType , LU.START_TIME AS startTime , LU.END_TIME AS endTime
, CASE WHEN LU.REQ_ID IS NULL THEN LU.LEAVE_DAYS ELSE ( SELECT SUM(X.LEAVE_DAYS) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = LU.CMPNY_CD AND X.REQ_ID = LU.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) END AS leaveDays , LU.LEAVE_MINUTES AS leaveMinutes
FROM TB_USER_LEAVE_USE LU
/* 기간형(START_DATE~END_DATE) 연차를 일자 단위로 전개한다. 양 컬럼 모두 varchar(8) YYYYMMDD 이므로 date_seq 의 DATE 값을 DATE_FORMAT 으로 맞춰 비교한다. */ INNER JOIN date_seq D ON DATE_FORMAT(D.D, '%Y%m%d') BETWEEN LU.START_DATE AND LU.END_DATE
/* 이름·부서 출처. 부서 판정은 U.NODE_CD 단일 출처. */ INNER JOIN TB_USER U ON U.CMPNY_CD = LU.CMPNY_CD AND U.USER_CD = LU.USER_CD
LEFT JOIN TB_SITE_NODE N ON N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = LU.SITE_CD AND N.NODE_CD = U.NODE_CD
/* 연차 종류명. 조인 키는 tb_leave_type_mgmt PK(CMPNY_CD, LEAVE_CD) 복합. */ LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = LU.CMPNY_CD AND LT.LEAVE_CD = LU.LEAVE_CD
WHERE LU.CMPNY_CD = #{gvCmpnyCd} AND LU.SITE_CD = #{siteCd} AND LU.LEAVE_STATUS = 'CONFIRMED' AND LU.DEL_YN = 'N' /* 월 교차 조건(IDX_LEAVE_USE_SITE 활용). LEAVE_STATUS 값은 CANCELLED(L 두 개)와 짝. */ AND LU.START_DATE <= #{monthEnd} AND LU.END_DATE >= #{monthStart}
AND ( LU.REQ_ID IS NULL OR LU.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = LU.CMPNY_CD AND X.REQ_ID = LU.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) ) /* SEC-A16-04: 퇴사자는 퇴사일이 속한 월까지만 노출한다(재직 중이던 과거월 이력은 보존, 퇴사 후 월에는 성명이 계속 조회되지 않게 차단 — 현황 화면 관례 attd07/11/15 취지). USE_YN 은 조건에 두지 않는다(비활성 계정 != 퇴사 — 재직자 이력 소실 방지). */ AND (U.WITHDRAWAL_DATE IS NULL OR U.WITHDRAWAL_DATE >= #{monthStart}) /* SEC-A16-05(2026-08-28): 사업장 이동자의 과거 연차 이력 보존 — 사업장 스코프는 "연차가 기록된 사업장"(LU.SITE_CD, 위 108행)만으로 판정한다. 사용자의 현재 소속(U.SITE_CD)이 기록 당시와 달라도(사업장 이동) 이력은 그대로 노출한다 — 바로 위 SEC-A16-04 퇴사자 처리와 동일한 "과거 재직 시점 이력은 보존" 원칙. 이 자리에는 원래 U.SITE_CD 를 조회 사업장과 비교하는 조건이 있었으나 사업장 이동자를 통째로 걸러내는 부작용이 있어 삭제했다(운영 DB 실사용자 재현 — 회사 DpqyoXhpHsAKhHxymCZP, 사용자 20260800002). ★주의: 부서(nodeCd) 필터의 비재귀 분기(아래 145~147행 부근)는 NODE_CD 가 사업장 간 중복 코드라(qa 결함 D1) 사업장 차원이 별도로 필요하다 — 그 조건은 삭제하지 않고 해당 분기 쪽으로 옮겼다(D1 재발 방지, 아래 SEC-A16-05 주석 참조). 주석 안에는 파라미터 표기(샵중괄호)를 쓰지 않는다(위 결함 D1 주석의 함정 재확인 — MyBatis 는 주석 안에서도 치환을 시도해 조회가 전멸한다). */
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.SITE_CD = #{siteCd} AND U.NODE_CD = #{nodeCd}
/* qa 결함 D5: 동명이인/동일 시각 건의 순서가 비결정이 되지 않게 USER_CD, LEAVE_ID 로 tie-break 한다(LeaveDashboardMapper 관례). 셀 이름 노출 순서/상세 카드 순서가 조회마다 바뀌면 "외 N명"에 들어가는 사람이 달라져 사용자 혼란을 준다. */ ORDER BY D.D, U.USER_NM, LU.START_TIME, LU.USER_CD, LU.LEAVE_ID
